import json,pathlib
B=pathlib.Path(__file__).resolve().parents[1]
def source(n): return json.loads((B/'extracted'/f'{n:03d}.json').read_text(encoding='utf-8'))
def audit(s,status,facts,reason,pages,quote='NR'):
 return dict(standard=s,status=status,facts=facts,reason=reason,pages=pages,quote=quote)
def chain(rows,claim,summary,construct,indicator,item,dim,code,instrument,family,origin,scoring,result,direction,pages,valid='未报告构念效度检验',reliable='未报告',adapt='NR',typ='C2',overrides=[]):
 return dict(legacy_rows=rows,claim_quote=claim,claim_summary=summary,claim_type=typ,construct_raw=construct,indicator_raw=indicator,item_quote=item,dimension_code=dim,indicator_code=code,instrument_raw=instrument,tool_family_codes=family,tool_origin_code=origin,adaptation=adapt,response_scoring=scoring,validity_evidence=valid,reliability_evidence=reliable,result_quote=result,effect_direction=direction,pages=pages,audit_overrides=overrides)
def evaluation(n,seq,legacy,purpose,objects,evaluators,sources,setting,design,stages,N,sample,recruit,task,comp,proc,analysis,results,limits,ethics,evidence,audits,chains):
 return dict(eval_id=f'{n}-R{seq}',legacy_eval_ids=legacy,purpose_codes=purpose,object_codes=objects,evaluator_codes=evaluators,source_codes=sources,setting_code=setting,design_code=design,evaluation_stage_codes=stages,sample_n=N,sample_description=sample,recruitment=recruit,task=task,task_codes=[],constraint_codes=['NR'],constraints_raw='未报告明确影响测量选择的可行条件',comparator=comp,procedure=proc,analysis=analysis,actual_results=results,limitations=limits,ethics=ethics,evidence=evidence,audit=audits,chains=chains)
def save(n,domain,stage,func,role,users,context,context_ev,evals,ex=[],note='',gaps=[],corrections={}):
 d=source(n); out=dict(paper_id=n,title_match=True,reviewed_pages=[p['page'] for p in d['pages']],scope_note=note,domain_codes=domain,stage_codes=stage,ai_function_codes=func,ai_role_codes=role,target_user_codes=users,context_summary=context,context_evidence=context_ev,evaluations=evals,excluded_legacy_rows=ex,added_evidence_notes=note,category_gaps=gaps,metadata_corrections=corrections)
 old={x['_legacy_row'] for x in d['previous_chains']}; represented=[r for e in evals for c in e['chains'] for r in c['legacy_rows']]+[x['legacy_row'] for x in ex]
 assert old==set(represented),(n,old-set(represented),set(represented)-old)
 assert len(represented)==len(set(represented)),(n,'duplicate legacy row')
 (B/'agents'/f'paper_{n:03d}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
 print('saved',n,'evaluations',len(evals),'chains',sum(len(e['chains']) for e in evals))
def ev(field,page,quote):return dict(field=field,page=page,quote=quote)

